        raw["stress"][s] = -r[-1]/v * shock
        raw["mom20"][s] = mom[s]/(v*np.sqrt(20)+.01)
    if len(series) < 8: return
    def cum(r, n): return float(np.prod(1+r[-n:])-1)
    for s, r in series.items():
        peers = [cum(series[t], 5) for t in series if t != s]
        med5 = np.median(peers); med3 = np.median([cum(series[t],3) for t in series if t != s]); med2 = np.median([cum(series[t],2) for t in series if t != s])
        own5, own3, own2 = cum(r,5), cum(r,3), cum(r,2)
        raw["peer5"][s] = own5-med5
        raw["beta5"][s] = -(own5-med5)/(vol[s]*np.sqrt(5)+.005)
        raw["rev3"][s] = -(own3-med3)/(vol[s]*np.sqrt(3)+.005)
        raw["beta2"][s] = -(own2-med2)/(vol[s]*np.sqrt(2)+.005)
        # Small lag mixture reduces reliance on a single one-day reversal.
        raw["lagmix"][s] = .6*(-r[-1]/vol[s]) + .4*(-(own2-med2)/(vol[s]*np.sqrt(2)+.005))
    ranks = {k: rank(v) for k,v in raw.items()}
    score = {s: sum(FACTORS[k]*ranks[k][s] for k in FACTORS) for s in UNIVERSE}
    breadth = np.mean([mom[s] > 0 for s in mom])
    medv = float(np.median(list(vol.values())))
    high_risk = medv > .018 or breadth < .45
    inv_mean = np.mean([1/v for v in vol.values()])
    defensive = {"XAU", "US10Y", "CN10Y"}
    raw_target = {}
    for s in UNIVERSE:
        iv = min((1/vol.get(s, medv))/inv_mean, 1.5)
        tilt = 1.12 if high_risk and s in defensive else 1.
        raw_target[s] = max(score[s], .05) * (.85+.15*iv) * tilt
    rebalance_to_weights(bounded(raw_target))

